-- Phase 10b task 1: roles as a set. Generated by drizzle-kit, then the data
-- copy and the triggers were added by hand.
--
-- user_role holds translator, teacher and admin rows. The copy gives every
-- existing admin an admin row (user.role stays the legacy mirror).
-- Last admin: user_role_keep_one_admin_delete and _update refuse to remove
-- the last admin whose ban is not in force, like user_keep_one_admin (0007,
-- recreated by 0015) does on user.role. The delete trigger only fires while
-- the user still exists, so deleting an account (a cascade) is not refused:
-- account.delete guards that, as before.
-- Mirror: the user_role_mirror_* triggers keep user.role and the admin row in
-- step in both directions, so code that still writes only user.role (the
-- admin grant script, admin.users.setRole, Better Auth) cannot drift from
-- user_role before the code writes both. Every one is conditional, so they
-- stop after one hop.
CREATE TABLE `user_role` (
	`user_id` text NOT NULL,
	`role` text NOT NULL,
	`granted_by` text,
	`granted_at` integer NOT NULL,
	PRIMARY KEY(`user_id`, `role`),
	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`granted_by`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "user_role_role_check" CHECK("role" IN ('translator', 'teacher', 'admin'))
);
--> statement-breakpoint
CREATE INDEX `user_role_role_user_idx` ON `user_role` (`role`,`user_id`);--> statement-breakpoint
CREATE INDEX `user_role_granted_by_idx` ON `user_role` (`granted_by`);--> statement-breakpoint
INSERT OR IGNORE INTO `user_role` (`user_id`, `role`, `granted_by`, `granted_at`) SELECT `id`, 'admin', NULL, CAST(unixepoch('subsec') * 1000 AS INTEGER) FROM `user` WHERE `role` = 'admin';--> statement-breakpoint
CREATE TRIGGER `user_role_keep_one_admin_delete`
BEFORE DELETE ON `user_role`
WHEN OLD.`role` = 'admin'
	AND EXISTS (SELECT 1 FROM `user` WHERE `user`.`id` = OLD.`user_id`)
	AND NOT EXISTS (
		SELECT 1 FROM `user_role` AS `other`
		JOIN `user` AS `other_user` ON `other_user`.`id` = `other`.`user_id`
		WHERE `other`.`role` = 'admin'
			AND `other`.`user_id` <> OLD.`user_id`
			AND NOT (
				coalesce(`other_user`.`banned`, 0) = 1
				AND (
					`other_user`.`ban_expires` IS NULL
					OR `other_user`.`ban_expires` > CAST(unixepoch('subsec') * 1000 AS INTEGER)
				)
			)
	)
BEGIN
	SELECT RAISE(ABORT, 'last_admin');
END;--> statement-breakpoint
CREATE TRIGGER `user_role_keep_one_admin_update`
BEFORE UPDATE OF `user_id`, `role` ON `user_role`
WHEN OLD.`role` = 'admin'
	AND (NEW.`role` <> 'admin' OR NEW.`user_id` <> OLD.`user_id`)
	AND NOT EXISTS (
		SELECT 1 FROM `user_role` AS `other`
		JOIN `user` AS `other_user` ON `other_user`.`id` = `other`.`user_id`
		WHERE `other`.`role` = 'admin'
			AND `other`.`user_id` <> OLD.`user_id`
			AND NOT (
				coalesce(`other_user`.`banned`, 0) = 1
				AND (
					`other_user`.`ban_expires` IS NULL
					OR `other_user`.`ban_expires` > CAST(unixepoch('subsec') * 1000 AS INTEGER)
				)
			)
	)
BEGIN
	SELECT RAISE(ABORT, 'last_admin');
END;--> statement-breakpoint
CREATE TRIGGER `user_role_mirror_user_insert`
AFTER INSERT ON `user`
WHEN NEW.`role` = 'admin'
BEGIN
	INSERT OR IGNORE INTO `user_role` (`user_id`, `role`, `granted_by`, `granted_at`) VALUES (NEW.`id`, 'admin', NULL, CAST(unixepoch('subsec') * 1000 AS INTEGER));
END;--> statement-breakpoint
CREATE TRIGGER `user_role_mirror_user_promote`
AFTER UPDATE OF `role` ON `user`
WHEN NEW.`role` = 'admin' AND OLD.`role` <> 'admin'
BEGIN
	INSERT OR IGNORE INTO `user_role` (`user_id`, `role`, `granted_by`, `granted_at`) VALUES (NEW.`id`, 'admin', NULL, CAST(unixepoch('subsec') * 1000 AS INTEGER));
END;--> statement-breakpoint
CREATE TRIGGER `user_role_mirror_user_demote`
AFTER UPDATE OF `role` ON `user`
WHEN OLD.`role` = 'admin' AND NEW.`role` <> 'admin'
BEGIN
	DELETE FROM `user_role` WHERE `user_id` = OLD.`id` AND `role` = 'admin';
END;--> statement-breakpoint
CREATE TRIGGER `user_role_mirror_grant`
AFTER INSERT ON `user_role`
WHEN NEW.`role` = 'admin'
BEGIN
	UPDATE `user` SET `role` = 'admin' WHERE `id` = NEW.`user_id` AND `role` <> 'admin';
END;--> statement-breakpoint
CREATE TRIGGER `user_role_mirror_revoke`
AFTER DELETE ON `user_role`
WHEN OLD.`role` = 'admin'
BEGIN
	UPDATE `user` SET `role` = 'user' WHERE `id` = OLD.`user_id` AND `role` = 'admin';
END;
